 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    div = 5
    row_cuts = [r for r in range(h) if all(v == div for v in grid[r])]
    col_cuts = [c for c in range(w) if all(grid[r][c] == div for r in range(h))]
    def intervals(n, cuts):
        out, start = [], 0
        for cut in cuts:
            out.append((start, cut))
            start = cut + 1
        out.append((start, n))
        return out
    rs, cs = intervals(h, row_cuts), intervals(w, col_cuts)
    # The first tile of each row contains that row's color label.
    labels = []
    for r0, r1 in rs:
        vals = [grid[r][c] for r in range(r0, r1) for c in range(cs[0][0], cs[0][1]) if grid[r][c] != 0 and grid[r][c] != div]
        labels.append(max(set(vals), key=vals.count))
    # Find the unique nonempty tile whose color is not one of the row labels.
    motif = None
    for r0, r1 in rs:
        for c0, c1 in cs:
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, div)]
            if vals and any(v not in labels for v in vals):
                motif = [[grid[r][c] not in (0, div) for c in range(c0, c1)] for r in range(r0, r1)]
                break
        if motif is not None:
            break
    if motif is None:
        raise ValueError('pattern tile not found')
    out = [[0] * w for _ in range(h)]
    for r in row_cuts:
        out[r] = [div] * w
    for c in col_cuts:
        for r in range(h):
            out[r][c] = div
    for i, (r0, r1) in enumerate(rs):
        color = labels[i]
        for c0, c1 in cs:
            for dr in range(min(r1-r0, len(motif))):
                for dc in range(min(c1-c0, len(motif[dr]))):
                    if motif[dr][dc]:
                        out[r0+dr][c0+dc] = color
    return out
